import './CityCoverageSection.css';
import indiaMap from '../assets/india_map.svg';

const CityCoverageSection = () => {
  const cities = [
    { name: 'Delhi NCR', icon: <Landmark size={32} /> },
    { name: 'Bangalore', icon: <Building2 size={32} /> },
    { name: 'Pune', icon: <Building size={32} /> },
    { name: 'Hyderabad', icon: <Castle size={32} /> },
    { name: 'Lucknow', icon: <Tent size={32} /> }, // Tent looks a bit like architectural dome
    { name: 'Chennai', icon: <Hotel size={32} /> }
  ];

  // Coordinates for placing map pins (percentages relative to the map container)
  const mapPins = [
    { id: 'delhi', top: '25%', left: '33%', name: 'Delhi' },
    { id: 'lucknow', top: '35%', left: '42%', name: 'Lucknow' },
    { id: 'pune', top: '55%', left: '26%', name: 'Pune' },
    { id: 'hyderabad', top: '58%', left: '36%', name: 'Hyderabad' },
    { id: 'bangalore', top: '70%', left: '33%', name: 'Bangalore' },
    { id: 'chennai', top: '68%', left: '42%', name: 'Chennai' }
  ];

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { 
      opacity: 1, 
      transition: { staggerChildren: 0.1, delayChildren: 0.2 } 
    }
  };

  const itemVariants = {
    hidden: { y: 20, opacity: 0 },
    visible: { 
      y: 0, 
      opacity: 1,
      transition: { type: 'spring', stiffness: 100 }
    }
  };

  return (
    <div className="coverage-section">
      <div className="coverage-container">
        
        {/* Left Content - Typography & City Grid */}
        <div className="coverage-left">
          <motion.div 
            className="coverage-text-block"
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true, margin: "-100px" }}
          >
            <h2 className="coverage-title">
              Now serving 185+ cities<br />across India
            </h2>
            <p className="coverage-subtitle">
              Wherever you are, reliable car service is always within reach with Hyundai.
            </p>
          </motion.div>

          <motion.div 
            className="city-grid"
            variants={containerVariants}
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: "-100px" }}
          >
            {cities.map((city, idx) => (
              <motion.div key={idx} variants={itemVariants} className="city-card">
                <div className="city-icon-wrapper">
                  {city.icon}
                </div>
                <span className="city-name">{city.name}</span>
              </motion.div>
            ))}
          </motion.div>
        </div>

        {/* Right Content - Holographic Map */}
        <div className="coverage-right">
          <motion.div 
            className="map-container"
            initial={{ opacity: 0, scale: 0.9 }}
            whileInView={{ opacity: 1, scale: 1 }}
            viewport={{ once: true, margin: "-100px" }}
            transition={{ duration: 0.8, ease: "easeOut" }}
          >
            {/* The SVG Map Layer */}
            <div className="india-map-wrapper">
              <img 
                src={indiaMap} 
                alt="India Map" 
                className="india-map-image" 
              />
              
              {/* Map Pins */}
              {mapPins.map((pin) => (
                <div 
                  key={pin.id} 
                  className="map-pin" 
                  style={{ top: pin.top, left: pin.left }}
                  title={pin.name}
                >
                  <div className="pin-pulse"></div>
                  <MapPin size={16} className="pin-icon" />
                </div>
              ))}
            </div>
          </motion.div>
        </div>

      </div>
    </div>
  );
};

export default CityCoverageSection;

import React, { useState } from 'react';
import { useLocation } from 'react-router-dom';
import hyundaiLogo from '../assets/hyundai-logo.png';
import './Navbar.css';

const Navbar = () => {
  const location = useLocation();
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const [isAuthenticated, setIsAuthenticated] = useState(false);

  React.useEffect(() => {
    // Check if user or admin is logged in whenever location changes
    const isUser = localStorage.getItem('userAuth') === 'true';
    const isAdmin = localStorage.getItem('adminAuth') === 'true';
    setIsAuthenticated(isUser || isAdmin);
  }, [location.pathname]);

  return (
    <>
      {/* Top Utility Bar */}
      <div className="top-utility-bar">
        <div className="top-bar-content">
          <div className="top-bar-left">
            <span className="top-bar-text">Welcome to Premium Hyundai Service</span>
            <span className="top-divider">|</span>
            <span className="top-bar-text">Certified Mechanics</span>
          </div>
          <div className="top-bar-right">
            <a href="tel:9699938509" className="top-bar-link">
              <Phone size={14} /> 9699938509
            </a>
            <span className="top-divider">|</span>
            <span className="top-bar-link">Mon - Sat, 9:00 AM - 7:00 PM</span>
          </div>
        </div>
      </div>

      {/* Main Navigation */}
      <nav className="floating-navbar">
        <div className="nav-content">
          <Link to="/" className="brand">
            <img src={hyundaiLogo} alt="Hyundai Logo" className="brand-icon" style={{ height: '36px', width: 'auto', objectFit: 'contain' }} />
          </Link>

          <div className="nav-links">
            <Link to="/" className={`nav-link ${location.pathname === '/' ? 'active' : ''}`}>
              Home
            </Link>
            <div
              className={`nav-link dropdown-container ${['/parivahan', '/rto-info', '/owner-details', '/puc'].includes(location.pathname) ? 'active' : ''}`}
              onMouseEnter={() => setDropdownOpen(true)}
              onMouseLeave={() => setDropdownOpen(false)}
            >


            </div>
            {isAuthenticated && (
              <Link to="/my-garage" className={`nav-link ${location.pathname === '/my-garage' ? 'active' : ''}`}>
                My Garage
              </Link>
            )}
            <Link to="/car-services" className={`nav-link ${location.pathname === '/car-services' ? 'active' : ''}`}>
              Car Services
            </Link>
            <Link to="/social-media" className={`nav-link ${location.pathname === '/social-media' ? 'active' : ''}`}>
              Social Media
            </Link>
          </div>

          <div className="nav-actions">
            <a href="tel:9699938509" className="contact-chip-link">
              <div className="contact-chip">
                <Phone size={18} />
                <span>9699938509</span>
              </div>
            </a>
            {isAuthenticated ? (
              <div style={{ display: 'flex', gap: '10px' }}>
                <button
                  onClick={() => {
                    localStorage.removeItem('adminAuth');
                    localStorage.removeItem('userRole');
                    localStorage.removeItem('userAuth');
                    localStorage.removeItem('userEmail');
                    window.location.href = '/';
                  }}
                  className="login-btn"
                  style={{ background: 'rgba(239, 68, 68, 0.1)', color: '#ef4444', border: '1px solid rgba(239, 68, 68, 0.2)' }}
                >
                  Logout
                </button>
              </div>
            ) : (
              <Link to="/login" className="login-btn">
                <User size={18} />
                <span>Login</span>
              </Link>
            )}
          </div>
        </div>
      </nav>
    </>
  );
};

export default Navbar;

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './ServiceTabs.css';

const ServiceTabs = ({ onRegNumberChange }) => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('service');
  const [regNumber, setRegNumber] = useState('');
  const [mobileNumber, setMobileNumber] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [savedCars, setSavedCars] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const defaultCars = [
      { id: 1, make: 'Honda', model: 'City', reg: 'MH-12-AB-1234', year: 2020 },
      { id: 2, make: 'Hyundai', model: 'Creta', reg: 'MH-14-XY-9876', year: 2022 },
    ];
    const stored = JSON.parse(localStorage.getItem('myGarageCars'));
    if (stored && stored.length > 0) {
      setSavedCars(stored);
    } else {
      setSavedCars(defaultCars);
      localStorage.setItem('myGarageCars', JSON.stringify(defaultCars));
    }
  }, []);

  const tabs = [
    { id: 'service', label: 'Book Service', icon: <Settings size={18} /> },
  ];

  const formatRegNumber = (val) => {
    const clean = val.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
    let formatted = '';
    if (clean.length > 0) formatted += clean.substring(0, 2);
    if (clean.length > 2) formatted += '-' + clean.substring(2, 4);
    if (clean.length > 4) formatted += '-' + clean.substring(4, 6);
    if (clean.length > 6) formatted += '-' + clean.substring(6, 10);
    return formatted;
  };

  const handleAction = async (e) => {
    e.preventDefault();
    setErrorMsg('');

    if (activeTab !== 'service') {
      setErrorMsg('Coming Soon!');
      return;
    }

    if (!regNumber.trim() || regNumber.length < 10) {
      setErrorMsg('Please enter a valid registration number.');
      return;
    }

    const parts = regNumber.split('-');
    if (parts.length === 4) {
      if (parts[1] === '00' || parts[3] === '0000') {
        setErrorMsg('00 and 0000 are not valid in registration numbers.');
        return;
      }
    }

    if (!mobileNumber.trim()) {
      setErrorMsg('Please enter your mobile number.');
      return;
    }
    if (mobileNumber.length !== 10) {
      setErrorMsg('Please enter a valid 10-digit mobile number.');
      return;
    }
    if (!/^[6789]/.test(mobileNumber)) {
      setErrorMsg('Mobile number must start with 6-9.');
      return;
    }

    setIsLoading(true);

    try {
      const cleanRegNumber = regNumber.replace(/-/g, "");

      const response = await fetch(
        `http://localhost:5000/api/vehicle/${cleanRegNumber}`
      );

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message);
      }

      const vehicle = data.data.rc_details;

      navigate("/car-details", {
        state: {
          regNumber,
          vehicleData: vehicle,
          insurance: data.data.insurance,
          puc: data.data.puc,
          challans: data.data.challans,
          mobileNumber: mobileNumber,
        },
      });

    } catch (err) {
      console.error(err);
      setErrorMsg("Vehicle not found.");
    } finally {
      setIsLoading(false);
    }
  }; // Close handleAction

  const handleGarageSelect = async (car) => {
    setIsLoading(true);
    try {
      const cleanRegNumber = car.reg.replace(/-/g, "");
      const response = await fetch(`http://localhost:5000/api/vehicle/${cleanRegNumber}`);
      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message);
      }

      const vehicle = data.data.rc_details;

      navigate("/car-details", {
        state: {
          regNumber: car.reg,
          vehicleData: vehicle,
          insurance: data.data.insurance,
          puc: data.data.puc,
          challans: data.data.challans,
          mobileNumber: mobileNumber || '9999999999', // Pass current mobile number or default
        },
      });
    } catch (err) {
      console.error(err);
      setErrorMsg("Vehicle not found from API, but continuing with saved details.");
      // Fallback if API fails: still go to car-details but with minimal data
      navigate('/car-details', {
        state: {
          regNumber: car.reg,
          mobileNumber: mobileNumber || '9999999999',
          vehicleData: {
            rc_maker_desc: car.make,
            rc_maker_model: car.model,
            rc_fuel_desc: 'Petrol'
          }
        }
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleRemoveCar = (e, carId) => {
    e.stopPropagation();
    const updatedCars = savedCars.filter(c => c.id !== carId);
    setSavedCars(updatedCars);
    localStorage.setItem('myGarageCars', JSON.stringify(updatedCars));
  };

  const getButtonText = () => {
    if (isLoading) return 'Fetching details...';
    switch (activeTab) {
      case 'vehicle': return 'Search vehicle';
      case 'service': return 'Book car service';
      case 'car-insurance': return 'Get car quote';
      case 'bike-insurance': return 'Get bike quote';
      default: return 'Submit';
    }
  };

  // Framer Motion variants
  const contentVariants = {
    initial: { opacity: 0, y: 15 },
    animate: { opacity: 1, y: 0, transition: { duration: 0.3 } },
    exit: { opacity: 0, y: -15, transition: { duration: 0.2 } }
  };

  return (
    <div className="service-tabs-wrapper creative-tabs-wrapper">

      {/* Floating Pill Tabs */}
      <div className="creative-tabs-pill-container">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            className={`creative-tab-btn ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => {
              setActiveTab(tab.id);
              if (tab.id !== 'service' && tab.id !== 'my-garage') {
                setErrorMsg('Coming Soon!');
              } else {
                setErrorMsg('');
              }
            }}
            type="button"
          >
            {/* The sliding active background */}
            {activeTab === tab.id && (
              <motion.div
                className="creative-tab-active-bg"
                layoutId="activeTabPill"
                initial={false}
                transition={{ type: "spring", stiffness: 500, damping: 35 }}
              />
            )}
            <span className="creative-tab-content">
              {tab.icon}
              <span className="creative-tab-label">{tab.label}</span>
            </span>
          </button>
        ))}
      </div>

      {/* Main Detached Content Container */}
      <div className="creative-content-container">
        <AnimatePresence mode="wait">
          {activeTab === 'service' && (
            <motion.form
              key="form"
              variants={contentVariants}
              initial="initial"
              animate="animate"
              exit="exit"
              onSubmit={handleAction}
              className="creative-form-content"
            >
              <div className="creative-inputs-row">

                {/* Registration Input */}
                <div className="creative-input-group">
                  <div className="creative-ind-plate">
                    <svg width="10" height="10" viewBox="0 0 24 24">
                      <circle cx="12" cy="12" r="10" fill="none" stroke="#FBBF24" strokeWidth="3" />
                      <circle cx="12" cy="12" r="3" fill="#FBBF24" />
                    </svg>
                    <span>IND</span>
                  </div>
                  <div className="creative-input-divider" />
                  <div className="creative-input-block">
                    <label>Registration Number</label>
                    <input
                      type="text"
                      placeholder="MH-12-AB-1234"
                      value={regNumber}
                      onChange={(e) => {
                        const formatted = formatRegNumber(e.target.value);
                        setRegNumber(formatted);
                        if (onRegNumberChange) onRegNumberChange(formatted);
                        if (errorMsg) setErrorMsg('');
                      }}
                      maxLength={13}
                      required
                    />
                  </div>
                </div>

                {/* Mobile Input */}
                {activeTab !== 'vehicle' && (
                  <div className="creative-input-group">
                    <div className="creative-phone-icon">
                      <Phone size={20} />
                    </div>
                    <div className="creative-input-divider" />
                    <div className="creative-input-block">
                      <label>Mobile Number</label>
                      <input
                        type="tel"
                        placeholder="1234567890"
                        maxLength={10}
                        value={mobileNumber}
                        onChange={(e) => {
                          setMobileNumber(e.target.value.replace(/\D/g, ''));
                          if (errorMsg) setErrorMsg('');
                        }}
                        required
                      />
                    </div>
                  </div>
                )}

                {/* Action Button */}
                <motion.button
                  type="submit"
                  className="creative-action-btn"
                  whileHover={{ scale: 1.02, backgroundColor: '#f1f5f9' }}
                  whileTap={{ scale: 0.98 }}
                  disabled={isLoading}
                  style={{ opacity: isLoading ? 0.7 : 1, cursor: isLoading ? 'not-allowed' : 'pointer' }}
                >
                  {getButtonText()}
                </motion.button>
              </div>

              {errorMsg && (
                <motion.div
                  className="creative-error-msg"
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                >
                  {errorMsg}
                </motion.div>
              )}
            </motion.form>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

export default ServiceTabs;

import { useEffect, useState } from 'react';
import hyundaiLogo from '../assets/hyundai-logo.png';
import './SplashScreen.css';

const SplashScreen = ({ onComplete }) => {
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    // Simulate loading progress
    const interval = setInterval(() => {
      setProgress((prev) => {
        if (prev >= 100) {
          clearInterval(interval);
          return 100;
        }
        return prev + 2; // Speed of progress bar
      });
    }, 30);

    // After total time (approx 2.2s), trigger completion
    const timeout = setTimeout(() => {
      onComplete();
    }, 2200);

    return () => {
      clearInterval(interval);
      clearTimeout(timeout);
    };
  }, [onComplete]);

  return (
    <motion.div 
      className="splash-screen-container"
      initial={{ opacity: 1 }}
      exit={{ 
        opacity: 0, 
        scale: 1.1, 
        filter: 'blur(10px)',
        transition: { duration: 0.6, ease: 'easeInOut' } 
      }}
    >
      {/* Background ambient glow */}
      <div className="splash-ambient-glow"></div>

      <div className="splash-content">
        <motion.div
          className="splash-logo-wrapper"
          initial={{ scale: 0.8, opacity: 0, y: 20 }}
          animate={{ scale: 1, opacity: 1, y: 0 }}
          transition={{ 
            duration: 0.8, 
            ease: [0.16, 1, 0.3, 1], // Custom spring-like curve
            delay: 0.2 
          }}
        >
          <div className="splash-icon-box" style={{ background: 'transparent', boxShadow: 'none' }}>
            <img src={hyundaiLogo} alt="Hyundai Logo" style={{ height: '140px', width: 'auto', objectFit: 'contain' }} />
          </div>
        </motion.div>

        <motion.div 
          className="splash-loading-section"
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.6, duration: 0.5 }}
        >
          <div className="splash-progress-bar-container">
            <motion.div 
              className="splash-progress-bar"
              style={{ width: `${progress}%` }}
              layout
            />
          </div>
          <div className="splash-loading-text">
            Initializing Engine... {progress}%
          </div>
        </motion.div>
      </div>
    </motion.div>
  );
};

export default SplashScreen;

import { useState, useEffect } from 'react';

const COLORS = ['#0F62FE', '#FF6B00', '#10B981', '#8B5CF6', '#F59E0B', '#EF4444', '#3B82F6', '#14B8A6'];

export default function CategoryChart() {
  const [data, setData] = useState([{ name: 'No Data', value: 1 }]);

  useEffect(() => {
    fetch("http://localhost:5000/api/dashboard/categories")
      .then(res => res.json())
      .then(json => {
        if (Array.isArray(json) && json.length > 0) {
          setData(json);
        }
      })
      .catch(console.error);
  }, []);

  return (
    <div className="h-full w-full p-4 flex flex-col">
      <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 mb-4">Service Categories</h3>
      <div className="flex-1 w-full min-h-[250px] flex items-center justify-center">
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={data}
              cx="50%"
              cy="50%"
              innerRadius={60}
              outerRadius={80}
              paddingAngle={5}
              dataKey="value"
              stroke="none"
            >
              {data.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
              ))}
            </Pie>
            <Tooltip 
              contentStyle={{ backgroundColor: '#1E1E1E', borderColor: '#334155', borderRadius: '8px', color: '#fff' }}
            />
            <Legend verticalAlign="bottom" height={36} iconType="circle" />
          </PieChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';

export default function RevenueChart() {
  const [data, setData] = useState([]);

  useEffect(() => {
    fetch("http://localhost:5000/api/reports")
      .then(res => res.json())
      .then(json => {
        if (json.monthlyRevenue) {
           const formatted = json.monthlyRevenue.map(item => ({
             name: item.month,
             revenue: Number(item.revenue) || 0
           }));
           setData(formatted);
        }
      })
      .catch(err => console.error("Error fetching revenue chart data:", err));
  }, []);

  return (
    <div className="h-full w-full p-4 flex flex-col">
      <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 mb-4">Monthly Revenue</h3>
      <div className="flex-1 w-full min-h-[250px]">
        <ResponsiveContainer width="100%" height="100%">
          <AreaChart data={data} margin={{ top: 10, right: 10, left: 0, bottom: 0 }}>
            <defs>
              <linearGradient id="colorRevenue" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="#0F62FE" stopOpacity={0.3}/>
                <stop offset="95%" stopColor="#0F62FE" stopOpacity={0}/>
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#334155" opacity={0.2} />
            <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#64748b', fontSize: 12 }} dy={10} />
            <YAxis axisLine={false} tickLine={false} tick={{ fill: '#64748b', fontSize: 12 }} tickFormatter={(val) => `₹${val/1000}k`} dx={-10} />
            <Tooltip 
              contentStyle={{ backgroundColor: '#1E1E1E', borderColor: '#334155', borderRadius: '8px', color: '#fff' }}
              itemStyle={{ color: '#0F62FE' }}
              formatter={(value) => [`₹${value}`, 'Revenue']}
            />
            <Area type="monotone" dataKey="revenue" stroke="#0F62FE" strokeWidth={3} fillOpacity={1} fill="url(#colorRevenue)" />
          </AreaChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import { useNavigate } from "react-router-dom";
import { useState, useEffect } from "react";

export default function AdminLayout() {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    const isAuthenticated = localStorage.getItem('adminAuth') === 'true';
    if (!isAuthenticated) {
      navigate('/login');
    }
  }, [navigate]);

  return (
    <div className="flex h-screen overflow-hidden bg-gradient-to-br from-background-light to-slate-100 dark:from-background-dark dark:to-slate-900 text-slate-800 dark:text-slate-200 selection:bg-primary/30 selection:text-primary-dark dark:selection:text-white">
      {/* Sidebar */}
      <Sidebar isOpen={sidebarOpen} setIsOpen={setSidebarOpen} />

      {/* Main Content */}
      <div className="flex flex-col flex-1 overflow-hidden relative">
        {/* Background glow effects */}
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] rounded-full bg-primary/5 blur-[100px] pointer-events-none"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] rounded-full bg-accent/5 blur-[100px] pointer-events-none"></div>

        <Topbar toggleSidebar={() => setSidebarOpen(!sidebarOpen)} />

        {/* Scrollable Page Content */}
        <main className="flex-1 overflow-y-auto p-4 md:p-6 lg:p-8 custom-scrollbar relative z-10">
          <Outlet />
        </main>
      </div>
    </div>
  );
}

import { useLocation, useNavigate } from "react-router-dom";
import { 
  LayoutDashboard, 
  Users, 
  CalendarCheck, 
  Wrench, 
  FileText, 
  BarChart3, 
  Settings
} from "lucide-react";
import { cn } from "../../utils/cn";
import hyundaiLogo from "../../assets/hyundai-logo.png";

const navigation = [
  { name: "Dashboard", href: "/admin", icon: LayoutDashboard },
  { name: "Customers", href: "/admin/customers", icon: Users },
  { name: "Bookings", href: "/admin/bookings", icon: CalendarCheck },
  { name: "Services", href: "/admin/services", icon: Wrench },
  { name: "Invoices", href: "/admin/invoices", icon: FileText },
  { name: "Reports", href: "/admin/reports", icon: BarChart3 },
  { name: "Staff Management", href: "/admin/staff", icon: Users },
  { name: "Settings", href: "/admin/settings", icon: Settings },
];

export default function Sidebar({ isOpen, setIsOpen }) {
  const location = useLocation();
  const navigate = useNavigate();
  const role = localStorage.getItem("userRole") || "Super Admin";

  const filteredNavigation = navigation.filter(item => {
    if (role === "Super Admin" || role === "SUPER_ADMIN") return true;
    if (role === "Sub Admin" || role === "Manager" || role === "MANAGER") {
      return ["Customers", "Bookings", "Services", "Invoices", "Staff Management"].includes(item.name);
    }
    return true; // fallback
  });

  return (
    <>
      {/* Mobile Backdrop */}
      {isOpen && (
        <div 
          className="fixed inset-0 z-40 bg-black/50 md:hidden"
          onClick={() => setIsOpen(false)}
        />
      )}

      {/* Sidebar */}
      <div 
        className={cn(
          "fixed inset-y-0 left-0 z-50 w-64 glass-panel border-r-0 border-r-white/10 transition-transform duration-300 md:static md:translate-x-0 flex flex-col",
          isOpen ? "translate-x-0" : "-translate-x-full"
        )}
      >
        <div className="flex h-20 shrink-0 items-center justify-between px-6 border-b border-slate-200/50 dark:border-slate-700/50">
          <Link to="/admin" className="flex items-center gap-2">
            <img src={hyundaiLogo} alt="Hyundai Logo" style={{ height: '40px', width: 'auto', objectFit: 'contain' }} />
          </Link>
          <button 
            className="md:hidden text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white"
            onClick={() => setIsOpen(false)}
          >
            <ChevronLeft className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto py-6 custom-scrollbar">
          <nav className="space-y-2 px-4">
            {filteredNavigation.map((item) => {
              const isActive = location.pathname === item.href;
              return (
                <Link
                  key={item.name}
                  to={item.href}
                  className={cn(
                    "flex items-center gap-3 px-4 py-3 text-sm font-medium rounded-xl transition-all duration-300 relative group overflow-hidden",
                    isActive 
                      ? "bg-primary/10 text-primary dark:text-white border border-primary/20 shadow-[0_0_15px_rgba(0,44,95,0.15)] dark:shadow-[0_0_15px_rgba(255,255,255,0.1)]" 
                      : "text-slate-600 dark:text-slate-400 hover:bg-slate-100/50 dark:hover:bg-slate-800/50 hover:text-slate-900 dark:hover:text-slate-200 border border-transparent"
                  )}
                  onClick={() => window.innerWidth < 768 && setIsOpen(false)}
                >
                  {/* Glowing line for active item */}
                  {isActive && <div className="absolute left-0 top-1/4 bottom-1/4 w-1 bg-primary dark:bg-white rounded-r-full shadow-lg shadow-primary/30"></div>}
                  
                  <item.icon className={cn("w-5 h-5 shrink-0 transition-colors duration-300 relative z-10", isActive ? "text-primary dark:text-white" : "text-slate-400 dark:text-slate-500 group-hover:text-primary dark:group-hover:text-slate-300")} />
                  <span className="relative z-10">{item.name}</span>
                </Link>
              );
            })}
          </nav>
        </div>
        
        <div className="p-5 border-t border-slate-200/50 dark:border-slate-700/50">
          <button 
            onClick={() => {
              localStorage.removeItem('adminAuth');
              localStorage.removeItem('userRole');
              navigate('/');
            }}
            className="flex items-center gap-3 px-4 py-3 w-full text-sm font-medium text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/10 hover:bg-red-100 dark:hover:bg-red-900/30 rounded-xl transition-all duration-300 border border-red-100 dark:border-red-900/20"
          >
            <LogOut className="w-5 h-5 shrink-0" />
            Logout
          </button>
        </div>
      </div>
    </>
  );
}

import { useState, useEffect } from "react";

export default function Topbar({ toggleSidebar }) {
  const [isDark, setIsDark] = useState(
    localStorage.getItem("theme") === "dark" ||
    (!("theme" in localStorage) && window.matchMedia("(prefers-color-scheme: dark)").matches)
  );

  useEffect(() => {
    if (isDark) {
      document.documentElement.classList.add("dark");
      localStorage.setItem("theme", "dark");
    } else {
      document.documentElement.classList.remove("dark");
      localStorage.setItem("theme", "light");
    }
  }, [isDark]);

  return (
    <header className="h-20 shrink-0 glass-header flex items-center justify-between px-4 sm:px-6 lg:px-8 transition-colors duration-200">
      <div className="flex items-center gap-4 flex-1">
        <button 
          onClick={toggleSidebar}
          className="text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white md:hidden"
        >
          <Menu className="w-6 h-6" />
        </button>

        <div className="relative max-w-md w-full hidden sm:block">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-4 w-4 text-slate-400 dark:text-slate-500" />
          </div>
          <input 
            type="text" 
            placeholder="Search dashboard..." 
            className="input-field pl-10 rounded-full bg-slate-100/50 dark:bg-slate-900/30 border-transparent hover:bg-slate-100 dark:hover:bg-slate-900/50 focus:bg-white dark:focus:bg-slate-800 transition-all"
          />
        </div>
      </div>

      <div className="flex items-center gap-2 sm:gap-4">
        <button className="relative p-2.5 text-slate-500 hover:text-primary dark:text-slate-400 dark:hover:text-white rounded-full hover:bg-primary/5 dark:hover:bg-slate-800 transition-all duration-300">
          <Bell className="w-5 h-5" />
          <span className="absolute top-2 right-2 w-2 h-2 bg-accent rounded-full border-2 border-white dark:border-background-dark animate-pulse"></span>
        </button>
        
        <button 
          onClick={() => setIsDark(!isDark)}
          className="p-2.5 text-slate-500 hover:text-primary dark:text-slate-400 dark:hover:text-white rounded-full hover:bg-primary/5 dark:hover:bg-slate-800 transition-all duration-300"
        >
          {isDark ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
        </button>

        <div className="h-8 w-px bg-border-light dark:bg-border-dark mx-1"></div>

        <button className="flex items-center gap-3 hover:opacity-80 transition-opacity pl-2">
          <div className="text-right hidden sm:block">
            <p className="text-sm font-semibold text-slate-900 dark:text-white leading-tight">
              {localStorage.getItem("userName") || (localStorage.getItem("userRole") === "Super Admin" ? "Admin User" : `${localStorage.getItem("userRole") || "Super"} User`)}
            </p>
            <p className="text-xs text-slate-500 dark:text-slate-400">{localStorage.getItem("userRole") || "Super Admin"}</p>
          </div>
          <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-primary to-primary-dark text-white shadow-lg shadow-primary/30 flex items-center justify-center font-bold border-2 border-white dark:border-slate-800">
            <User className="w-5 h-5" />
          </div>
        </button>
      </div>
    </header>
  );
}

import { useEffect } from "react";
import { cn } from "../../utils/cn";

export default function Modal({ isOpen, onClose, title, children, maxWidth = "max-w-md", fullScreen = false }) {
  // Close on Escape key
  useEffect(() => {
    const handleEscape = (e) => {
      if (e.key === "Escape") onClose();
    };
    if (isOpen) document.addEventListener("keydown", handleEscape);
    return () => document.removeEventListener("keydown", handleEscape);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] overflow-y-auto">
      <div className={cn("flex min-h-full items-center justify-center", fullScreen ? "p-0" : "p-4 sm:p-6")}>
        {/* Backdrop */}
        <div 
          className="fixed inset-0 bg-slate-900/50 transition-opacity" 
          onClick={onClose}
        />
        
        {/* Modal Content */}
        <div className={cn(
          "relative w-full bg-white dark:bg-slate-900 shadow-xl flex flex-col",
          fullScreen ? "min-h-screen rounded-none border-0" : "rounded-xl border border-slate-200 dark:border-slate-800 my-8 max-h-[90vh]",
          !fullScreen && maxWidth
        )}>
          {/* Header */}
          <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/50 rounded-t-xl shrink-0">
            <h3 className="text-lg font-semibold text-slate-900 dark:text-white">{title}</h3>
            <button 
              onClick={onClose}
              className="p-1.5 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 rounded-lg transition-colors bg-white dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Body */}
          <div className="px-6 py-4 overflow-y-auto custom-scrollbar flex-1">
            {children}
          </div>
        </div>
      </div>
    </div>
  );
}

export default function Table({ columns, data, actions, onAction }) {
  return (
    <div className="premium-table-container">
      <table className="premium-table">
        <thead>
          <tr>
            {columns.map((col, idx) => (
              <th key={idx} className="premium-th">{col.header}</th>
            ))}
            {actions && <th className="premium-th text-right">Actions</th>}
          </tr>
        </thead>
        <tbody>
          {data.map((row, rowIdx) => (
            <tr key={rowIdx} className="premium-tr">
              {columns.map((col, colIdx) => (
                <td key={colIdx} className="premium-td">
                  {col.cell ? col.cell(row, rowIdx) : row[col.accessor]}
                </td>
              ))}
              {actions && (
                <td className="premium-td text-right">
                  <div className="flex items-center justify-end gap-3">
                    {actions.includes('view') && (
                      <button onClick={() => onAction && onAction('view', row)} className="text-slate-400 hover:text-primary transition-colors" title="View">
                        <Eye className="w-4 h-4" />
                      </button>
                    )}
                    {actions.includes('edit') && (
                      <button onClick={() => onAction && onAction('edit', row)} className="text-slate-400 hover:text-primary-dark transition-colors" title="Edit">
                        <Edit className="w-4 h-4" />
                      </button>
                    )}
                    {actions.includes('delete') && (
                      <button onClick={() => onAction && onAction('delete', row)} className="text-slate-400 hover:text-red-500 transition-colors" title="Delete">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </td>
              )}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

