      padding: '20px 24px',
      boxShadow: '0 4px 20px rgba(0,0,0,0.06)',
      border: '1px solid rgba(226, 232, 240, 0.8)'
    },
    cardHeader: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '16px'
    },
    sidebarTitle: {
      fontSize: '16px',
      fontWeight: 700,
      color: '#1e293b',
      margin: 0
    },
    vehicleBadge: {
      display: 'flex',
      alignItems: 'center',
      gap: '6px',
      fontSize: '12px',
      fontWeight: 600,
      color: '#22c55e',
      background: '#f0fdf4',
      padding: '4px 12px',
      borderRadius: '12px'
    },
    badgeDot: {
      width: '6px',
      height: '6px',
      borderRadius: '50%',
      background: '#22c55e',
      display: 'inline-block'
    },
    vehicleInfo: {
      display: 'flex',
      flexDirection: 'column',
      gap: '10px'
    },
    vehicleRow: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      padding: '6px 0',
      borderBottom: '1px solid #f1f5f9'
    },
    vehicleLabel: {
      fontSize: '13px',
      color: '#94a3b8',
      fontWeight: 500
    },
    vehicleValue: {
      fontSize: '14px',
      fontWeight: 600,
      color: '#1e293b'
    },
    warrantyRow: {
      borderBottom: 'none',
      paddingBottom: 0
    },
    warrantyActive: {
      display: 'flex',
      alignItems: 'center',
      gap: '6px',
      color: '#22c55e',
      fontSize: '13px'
    },
    summaryItems: {
      display: 'flex',
      flexDirection: 'column',
      gap: '8px'
    },
    summaryRow: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      fontSize: '14px',
      color: '#475569'
    },
    summaryMain: {
      fontWeight: 600,
      color: '#1e293b',
      paddingBottom: '8px',
      borderBottom: '1px solid #f1f5f9'
    },
    summaryHighlight: {
      color: '#3b82f6',
      fontWeight: 700
    },
    summarySub: {
      fontSize: '13px',
      color: '#64748b',
      paddingLeft: '8px'
    },
    textFree: {
      color: '#22c55e',
      fontWeight: 600
    },
    summaryDivider: {
      borderTop: '1px dashed #e2e8f0',
      margin: '12px 0'
    },
    summaryTotals: {
      display: 'flex',
      flexDirection: 'column',
      gap: '8px',
      paddingTop: '4px'
    },
    summaryGrand: {
      fontSize: '18px',
      fontWeight: 800,
      color: '#1e293b',
      borderTop: '2px solid #e2e8f0',
      paddingTop: '12px',
      marginTop: '4px'
    },
    summaryActions: {
      display: 'flex',
      flexDirection: 'column',
      gap: '10px',
      marginTop: '20px'
    },
    btnPrimary: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      gap: '8px',
      background: 'linear-gradient(135deg, #2563eb, #3b82f6)',
      color: 'white',
      border: 'none',
      padding: '14px 24px',
      borderRadius: '12px',
      fontSize: '15px',
      fontWeight: 600,
      cursor: 'pointer',
      transition: 'all 0.2s',
      boxShadow: '0 4px 14px rgba(37, 99, 235, 0.35)',
      width: '100%'
    },
    btnOutline: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      gap: '8px',
      background: 'white',
      color: '#475569',
      border: '2px solid #e2e8f0',
      padding: '12px 24px',
      borderRadius: '12px',
      fontSize: '14px',
      fontWeight: 600,
      cursor: 'pointer',
      transition: 'all 0.2s',
      width: '100%'
    },
    bottom: {
      maxWidth: '1440px',
      margin: '40px auto 0',
      background: 'white',
      borderRadius: '16px',
      padding: '32px 40px',
      boxShadow: '0 4px 20px rgba(0,0,0,0.06)',
      border: '1px solid rgba(226, 232, 240, 0.8)'
    },
    bottomTitle: {
      textAlign: 'center',
      fontSize: '22px',
      fontWeight: 700,
      color: '#1e293b',
      margin: '0 0 24px 0'
    },
    featuresGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))',
      gap: '16px'
    },
    featureItem: {
      display: 'flex',
      alignItems: 'center',
      gap: '10px',
      padding: '12px 16px',
      background: '#f8fafc',
      borderRadius: '10px',
      transition: 'all 0.2s'
    },
    featureIcon: {
      color: '#3b82f6',
      display: 'flex',
      alignItems: 'center'
    },
    featureText: {
      fontSize: '13px',
      fontWeight: 500,
      color: '#334155'
    }
  };

  // Slider thumb styles via style tag
  const sliderStyles = `
    .bss-slider::-webkit-slider-thumb {
      -webkit-appearance: none;
      appearance: none;
      width: 20px;
      height: 20px;
      border-radius: 50%;
      background: white;
      cursor: pointer;
      box-shadow: 0 0 0 4px #3b82f6, 0 4px 12px rgba(0,0,0,0.15);
      transition: all 0.15s;
    }
    .bss-slider::-webkit-slider-thumb:hover {
      transform: scale(1.1);
    }
    .bss-slider::-moz-range-thumb {
      width: 20px;
      height: 20px;
      border-radius: 50%;
      background: white;
      cursor: pointer;
      box-shadow: 0 0 0 4px #3b82f6, 0 4px 12px rgba(0,0,0,0.15);
      border: none;
    }
    .bss-slider:focus {
      outline: none;
    }
    @media (max-width: 1150px) {
      .bss-main-grid { grid-template-columns: 1fr !important; gap: 40px !important; }
      .bss-right-pane { position: static !important; }
    }
    @media (max-width: 640px) {
      .bss-services-grid { grid-template-columns: 1fr !important; }
      .bss-features-grid { grid-template-columns: repeat(2, 1fr) !important; }
      .bss-slider-container { padding: 16px !important; }
      .bss-parts-section { padding: 16px !important; }
    }
  `;

  return (
    <div style={styles.container}>
      <style>{sliderStyles}</style>
      <div style={styles.main} className="bss-main-grid">
        {/* Left Pane */}
        <div style={styles.leftPane}>
          {/* Header */}
          <div style={styles.header}>
            <button style={styles.backBtn} onClick={() => navigate(-1)}>
              <ArrowLeft size={20} />
              <span>Back</span>
            </button>

          </div>

          {/* Title */}
          <motion.div
            initial="hidden"
            animate="visible"
            variants={fadeInUp}
            style={styles.titleSection}
          >
            <h1 style={styles.mainTitle}>Select Service Interval</h1>
            <p style={styles.subtitle}>Choose the right maintenance schedule for your vehicle's battery health</p>
          </motion.div>



          {/* Slider */}
          <motion.div
            initial="hidden"
            animate="visible"
            variants={fadeInUp}
            style={styles.sliderContainer}
          >
            <div style={styles.sliderHeader}>
              <div style={styles.sliderLabel}>
                <Calendar size={18} />
                <span>{selectedInterval || 'Slide to select interval'}</span>
              </div>
              {selectedInterval && (
                <span style={styles.sliderIndex}>
                  {serviceIntervals.indexOf(selectedInterval) + 1} of {serviceIntervals.length}
                </span>
              )}
            </div>
            <div style={styles.sliderWrapper}>
              <input
                type="range"
                min="0"
                max={serviceIntervals.length - 1}
                step="1"
                value={selectedInterval ? serviceIntervals.indexOf(selectedInterval) : 0}
                onChange={(e) => setSelectedInterval(serviceIntervals[parseInt(e.target.value)])}
                style={styles.slider}
                className="bss-slider"
              />
              <div style={styles.sliderTicks}>
                <span>{serviceIntervals[0]}</span>
                <span>{serviceIntervals[Math.floor(serviceIntervals.length / 2)]}</span>
                <span>{serviceIntervals[serviceIntervals.length - 1]}</span>
              </div>
            </div>
          </motion.div>

          {/* Parts Table */}
          <AnimatePresence mode="wait">
            {(selectedInterval || selectedPackage) && (
              <motion.div
                key="parts-table"
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                transition={{ duration: 0.4 }}
                style={styles.partsSection}
              >
                <div style={styles.sectionHeader}>
                  <h2 style={styles.sectionTitle}>Parts & Pricing Details</h2>
                  <span style={styles.sectionBadge}>{currentParts.length} items</span>
                </div>
                <div style={styles.tableWrapper}>
                  <table style={styles.partsTable}>
                    <thead style={styles.tableHead}>
                      <tr>
                        <th style={styles.tableHeadCell}>Component</th>
                        <th style={{ ...styles.tableHeadCell, textAlign: 'right' }}>Price (INR)</th>
                      </tr>
                    </thead>
                    <tbody>
                      {currentParts.map((part, idx) => {
                        const isExtraSelected = selectedExtraParts.some(p => p.id === part.id);
                        return (
                          <motion.tr
                            key={idx}
                            initial={{ opacity: 0, x: -10 }}
                            animate={{ opacity: 1, x: 0 }}
                            transition={{ delay: idx * 0.05 }}
                            style={{ ...styles.tableRow, ...(part.isDefault || isExtraSelected ? styles.activeRow : {}) }}
                          >
                            <td style={styles.tableCell}>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                {!part.isIncludedIn1500 && !part.isDefault && (
                                  <input 
                                    type="checkbox" 
                                    checked={isExtraSelected}
                                    onChange={() => handleExtraPartToggle(part)}
                                    style={{ cursor: 'pointer', width: '16px', height: '16px', accentColor: '#3b82f6' }}
                                  />
                                )}
                                {(!part.isIncludedIn1500 && part.isDefault) && (
                                  <Check size={16} color="#22c55e" />
                                )}
                                <span style={styles.partIcon}>{part.icon}</span>
                                <span style={styles.partName}>{part.name}</span>
                              </div>
                            </td>
                            <td style={{ ...styles.tableCell, textAlign: 'right' }}>
                              {part.isIncludedIn1500 ? (
                                <span style={styles.partFree}>Included</span>
                              ) : part.isDefault ? (
                                <span style={styles.partPrice}>{formatPrice(part.basePrice)}</span>
                              ) : (
                                <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: '2px' }}>
                                  {!isExtraSelected && (
                                    <span style={{ color: '#94a3b8', fontSize: '11px', fontWeight: 600, textTransform: 'uppercase' }}>Not Included</span>
                                  )}
                                  <span style={{ ...styles.partPrice, color: isExtraSelected ? '#3b82f6' : '#64748b' }}>
                                    {isExtraSelected ? formatPrice(part.basePrice) : `+ ${formatPrice(part.basePrice)}`}
                                  </span>
                                </div>
                              )}
                            </td>
                          </motion.tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* Add-ons */}
          <motion.div
            initial="hidden"
            whileInView="visible"
            viewport={{ once: true, margin: "-100px" }}
            variants={fadeInUp}
            style={styles.addonsSection}
          >
            <div style={styles.sectionHeader}>
              <h2 style={styles.sectionTitle}>Add-on Services</h2>
              <span style={styles.sectionBadge}>{selectedAddons.length} selected</span>
            </div>
            <p style={styles.subtitle}>Enhance your service with these additional care options</p>

            <motion.div
              style={styles.servicesGrid}
              variants={staggerContainer}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              className="bss-services-grid"
            >
              {individualServices.map((service, idx) => {
                const isSelected = selectedAddons.some(a => a.id === service.id);
                return (
                  <motion.div
                    key={service.id}
                    style={{ ...styles.serviceCard, ...(isSelected ? styles.serviceSelected : {}) }}
                    variants={fadeInUp}
                    whileHover={{ y: -4, transition: { duration: 0.2 } }}
                    onClick={() => handleAddonToggle(service)}
                  >
                    <div style={styles.serviceIconWrapper}>
                      <div style={styles.serviceIcon}>{service.icon}</div>
                      {isSelected && <CircleCheck size={18} style={styles.serviceCheck} />}
                    </div>
                    <div style={styles.serviceInfo}>
                      <div style={styles.serviceTitle}>{service.title}</div>
                      <div style={styles.serviceDesc}>{service.desc}</div>
                    </div>
                    <div style={styles.serviceAction}>
                      <div style={styles.servicePrice}>
                        {service.freeText ? service.freeText : formatPrice(service.price)}
                      </div>
                      <button
                        style={{ ...styles.addonBtn, ...(isSelected ? styles.addonAdded : {}) }}
                        onClick={(e) => {
                          e.stopPropagation();
                          handleAddonToggle(service);
                        }}
                      >
                        {isSelected ? <Check size={16} /> : <Plus size={16} />}
                      </button>
                    </div>
                  </motion.div>
                );
              })}
            </motion.div>
          </motion.div>
        </div>

        {/* Right Sidebar */}
        <div style={styles.rightPane} className="bss-right-pane">
          <motion.div
            initial={{ opacity: 0, x: 30 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ duration: 0.6 }}
            style={styles.sidebar}
          >
            {/* Vehicle Details */}
            <div style={styles.sidebarCard}>
              <div style={styles.cardHeader}>
                <h3 style={styles.sidebarTitle}>Vehicle Details</h3>
                <div style={styles.vehicleBadge}>
                  <span style={styles.badgeDot}></span>
                  Active
                </div>
              </div>
              <div style={styles.vehicleInfo}>
                <div style={styles.vehicleRow}>
                  <span style={styles.vehicleLabel}>Registration</span>
                  <span style={styles.vehicleValue}>{regNumber}</span>
                </div>
                <div style={styles.vehicleRow}>
                  <span style={styles.vehicleLabel}>Brand</span>
                  <span style={styles.vehicleValue}>{brand}</span>
                </div>
                <div style={styles.vehicleRow}>
                  <span style={styles.vehicleLabel}>Model</span>
                  <span style={styles.vehicleValue}>{model}</span>
                </div>
                <div style={styles.vehicleRow}>
                  <span style={styles.vehicleLabel}>Fuel Type</span>
                  <span style={styles.vehicleValue}>{fuel}</span>
                </div>
                
              </div>
            </div>

            {/* Order Summary */}
            <div style={styles.sidebarCard}>
              <h3 style={styles.sidebarTitle}>Order Summary</h3>

              <div style={styles.summaryItems}>
                
                <div style={{ ...styles.summaryRow, ...styles.summaryMain }}>
                  <span>Service Interval</span>
                  <span style={styles.summaryHighlight}>
                    {selectedInterval || 'Not Selected'}
                  </span>
                </div>

                {currentParts.filter(p => p.isDefault).length > 0 ? (
                  currentParts.filter(p => p.isDefault).map((part, idx) => (
                    <div key={idx} style={{ ...styles.summaryRow, ...styles.summarySub }}>
                      <span>{part.icon} {part.name}</span>
                      <span>{formatPrice(part.basePrice)}</span>
                    </div>
                  ))
                ) : (
                  <div style={{ ...styles.summaryRow, ...styles.summarySub }}>
                    <span>🔍 Basic Inspection</span>
                    <span style={styles.textFree}>Free</span>
                  </div>
                )}

                {selectedExtraParts.map((part, idx) => (
                  <div key={`extra-${idx}`} style={{ ...styles.summaryRow, ...styles.summarySub }}>
                    <span>{part.icon} {part.name} <span style={{color: '#3b82f6', fontSize: '11px'}}>(Added)</span></span>
                    <span>{formatPrice(part.basePrice)}</span>
                  </div>
                ))}

                {selectedAddons.length > 0 && (
                  <>
                    <div style={styles.summaryDivider}></div>
                    {selectedAddons.map(addon => (
                      <div key={addon.id} style={{ ...styles.summaryRow, ...styles.summarySub }}>
                        <span>{addon.icon} {addon.title}</span>
                        <span>{formatPrice(addon.price)}</span>
                      </div>
                    ))}
                  </>
                )}
              </div>

              <div style={styles.summaryDivider}></div>

              <div style={styles.summaryTotals}>
                <div style={styles.summaryRow}>
                  <span>Subtotal</span>
                  <span>{formatPrice(subtotal)}</span>
                </div>
                <div style={styles.summaryRow}>
                  <span>GST (18%)</span>
                  <span>{formatPrice(gst)}</span>
                </div>
                <div style={{ ...styles.summaryRow, ...styles.summaryGrand }}>
                  <span>Grand Total</span>
                  <span>{formatPrice(grandTotal)}</span>
                </div>
              </div>

              <div style={styles.summaryActions}>
                <motion.button
                  style={styles.btnPrimary}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => {
                    if (!selectedInterval) {
                      alert("Please select a service interval first.");
                      return;
                    }
                    const partNames = currentParts.filter(p => p.price > 0).length > 0
                      ? 'Includes: ' + currentParts.filter(p => p.price > 0).map(p => p.name).join(', ')
                      : 'Basic Inspection';
                    const addonNames = selectedAddons.length > 0
                      ? ' | Addons: ' + selectedAddons.map(a => a.title).join(', ')
                      : '';
                    navigate('/garage-selection', {
                      state: {
                        vehicle: {
                          regNumber, brand, model, fuel,
                          batteryType: '12V 45Ah',
                          ownerName: location.state?.ownerName,
                          mobileNumber: location.state?.mobileNumber
                        },
                        package: {
                          name: `Service Interval: ${selectedInterval} (${partNames}${addonNames})`,
                          price: grandTotal
                        }
                      }
                    });
                  }}
                >
                  Select Garage
                  <ChevronRight size={18} />
                </motion.button>
              </div>
            </div>
          </motion.div>
        </div>
      </div>

      {/* Bottom Section */}
      <motion.div
        style={styles.bottom}
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        transition={{ duration: 0.6 }}
      >
        <h2 style={styles.bottomTitle}>Why Choose Us</h2>
        <div style={styles.featuresGrid} className="bss-features-grid">
          {features.map((feature, idx) => (
            <motion.div
              key={idx}
              style={styles.featureItem}
              initial={{ opacity: 0, scale: 0.9 }}
              whileInView={{ opacity: 1, scale: 1 }}
              viewport={{ once: true }}
              transition={{ delay: idx * 0.08 }}
              whileHover={{ y: -2 }}
            >
              <div style={styles.featureIcon}>{feature.icon}</div>
              <span style={styles.featureText}>{feature.text}</span>
            </motion.div>
          ))}
        </div>
      </motion.div>
    </div>
  );
};

export default BatteryServiceSelection;

import { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import '@google/model-viewer';
import './CarDetails.css';

const CarDetails = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const vehicleData = location.state?.vehicleData || {};

  // Extract brand, model, fuel from vehicleData if present
  const apiBrand = vehicleData.rc_maker_desc ? vehicleData.rc_maker_desc.split(' ')[0] : 'HYUNDAI';
  const apiModel = vehicleData.rc_maker_model || 'Grand i10 Nios';
  const apiFuel = vehicleData.rc_fuel_desc || 'Petrol';
  const apiOwner = vehicleData.rc_owner_name || '';

  // Brand, Model, Fuel States
  const [selectedBrand, setSelectedBrand] = useState(apiBrand.toUpperCase());
  const [selectedModel, setSelectedModel] = useState(apiModel);
  const [selectedFuel, setSelectedFuel] = useState(apiFuel);
  const [ownerName, setOwnerName] = useState(apiOwner);
  const [mobileNumber, setMobileNumber] = useState(location.state?.mobileNumber || '');

  // Dropdown open states
  const [brandDropdownOpen, setBrandDropdownOpen] = useState(false);
  const [modelDropdownOpen, setModelDropdownOpen] = useState(false);
  const [fuelDropdownOpen, setFuelDropdownOpen] = useState(false);

  const carData = {
    HYUNDAI: [
      'CRETA', 'I20', 'VERNA', 'VENUE', 'ALCAZAR', 'TUCSON', 'AURA', 'EXTER',
      'Grand i10 Nios', 'IONIQ 5', 'KONA ELECTRIC', 'I20 N LINE', 'VENUE N LINE',
      'SANTRO', 'EON', 'XCENT', 'ELANTRA', 'ACCENT', 'GETZ', 'SONATA', 'SANTA FE'
    ].sort(),
  };

  const fuelTypes = ['Petrol', 'Diesel', 'CNG', 'Electric'];

  const handleBrandSelect = (brand) => {
    setSelectedBrand(brand);
    if (carData[brand] && carData[brand].length > 0) {
      setSelectedModel(carData[brand][0]);
    }
    setBrandDropdownOpen(false);
  };

  const handleModelSelect = (model) => {
    setSelectedModel(model);
    setModelDropdownOpen(false);
  };

  const handleFuelSelect = (fuel) => {
    setSelectedFuel(fuel);
    setFuelDropdownOpen(false);
  };

  const handleNext = (e) => {
    e.preventDefault();
    navigate('/battery-service-selection', {
      state: {
        vehicleData: vehicleData,
        regNumber: location.state?.regNumber || vehicleData.rc_regn_no || '',
        brand: selectedBrand,
        model: selectedModel,
        fuel: selectedFuel,
        ownerName,
        mobileNumber
      }
    });
  };

  return (
    <div className="car-details-page-wrapper">
      <div className="split-layout-container">
        <button
          type="button"
          className="back-nav-arrow-btn"
          onClick={() => navigate(-1)}
          title="Go Back"
        >
          <ArrowLeft size={24} />
        </button>

        {/* Left Side: Inputs & Details selection form */}
        <div className="right-selection-pane">

          <div className="selection-card-container">
            <h2 className="selection-title">Book your car service</h2>
            <p className="selection-subtitle">Help us identify your car to get started</p>

            <form onSubmit={handleNext} className="car-selection-form">
              {/* Brand Field (Fixed) */}
              <div className="dropdown-field-wrapper">
                <div className="selector-field-btn" style={{ cursor: 'default', opacity: 0.9 }}>
                  <Car size={18} className="field-left-icon" />
                  <span className="field-value-text">{selectedBrand}</span>
                </div>
              </div>

              {/* Model Field (Fixed) */}
              <div className="dropdown-field-wrapper">
                <div className="selector-field-btn" style={{ cursor: 'default', opacity: 0.9 }}>
                  <Car size={18} className="field-left-icon" />
                  <span className="field-value-text" style={{ textTransform: 'none' }}>{selectedModel}</span>
                </div>
              </div>

              {/* Fuel Field (Fixed) */}
              <div className="dropdown-field-wrapper">
                <div className="selector-field-btn" style={{ cursor: 'default', opacity: 0.9 }}>
                  <Fuel size={18} className="field-left-icon" />
                  <span className="field-value-text" style={{ textTransform: 'none' }}>{selectedFuel}</span>
                </div>
              </div>

              {/* Owner Name Input (Fixed) */}
              <div className="dropdown-field-wrapper" style={{ marginBottom: '1.5rem' }}>
                <div className="selector-field-btn" style={{ cursor: 'default', opacity: 0.9 }}>
                  <input
                    type="text"
                    value={ownerName}
                    readOnly
                    placeholder="Owner Name"
                    style={{ width: '100%', paddingLeft: '1rem', textTransform: 'none', background: 'transparent', outline: 'none', cursor: 'default' }}
                  />
                </div>
              </div>

              {/* Next Action Button */}
              <button type="submit" className="booking-next-btn">
                Next
              </button>
            </form>
          </div>
        </div>

        {/* Right Side: 3D Model Marketing Pane */}
        <div className="left-marketing-pane">
          {/* Subtle gradient overlay to match aesthetic */}
