import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../../api/axiosConfig';
import toast from 'react-hot-toast';

const Bookings = () => {
  const queryClient = useQueryClient();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  
  const [formData, setFormData] = useState({
    customerId: '',
    vehicleId: '',
    status: 'Pending',
    complaints: ''
  });

  const { data: bookingsData, isLoading } = useQuery({
    queryKey: ['bookings'],
    queryFn: () => api.get('/bookings')
  });

  const mutation = useMutation({
    mutationFn: (bookingData) => {
      if (editingId) {
        return api.put(`/bookings/${editingId}`, bookingData);
      }
      return api.post('/bookings', bookingData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bookings'] });
      toast.success(editingId ? 'Booking updated successfully!' : 'Booking created successfully!');
      closeModal();
    },
    onError: (err) => {
      toast.error(err?.response?.data?.message || 'Something went wrong');
    }
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => api.delete(`/bookings/${id}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['bookings'] });
      toast.success('Booking deleted successfully!');
    }
  });

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    mutation.mutate(formData);
  };

  const handleDelete = (id) => {
    if(window.confirm('Are you sure you want to delete this booking?')) {
      deleteMutation.mutate(id);
    }
  };

  const openAddModal = () => {
    setEditingId(null);
    setFormData({ customerId: '', vehicleId: '', status: 'Pending', complaints: '' });
    setIsModalOpen(true);
  };

  const openEditModal = (booking) => {
    setEditingId(booking.id);
    setFormData({
      customerId: booking.customerId || '',
      vehicleId: booking.vehicleId || '',
      status: booking.status || 'Pending',
      complaints: booking.complaints || ''
    });
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  const getStatusColor = (status) => {
    const s = (status || 'Pending').toUpperCase();
    switch (s) {
      case 'PENDING': return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-500';
      case 'IN PROGRESS': return 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-500';
      case 'COMPLETED': return 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-500';
      case 'CANCELLED': return 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-500';
      case 'CONFIRMED': return 'bg-slate-100 text-slate-800 dark:bg-slate-800 dark:text-slate-300';
      default: return 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-300';
    }
  };

  if (isLoading) return <div className="p-8 text-center text-gray-500">Loading Bookings...</div>;

  const bookings = bookingsData?.data || [];

  return (
    <div className="glass-panel rounded-2xl overflow-hidden animate-fade-in">
      <div className="p-6 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center bg-white/50 dark:bg-slate-900/50">
        <h2 className="text-xl font-bold text-slate-900 dark:text-white">Service Bookings (Job Cards)</h2>
        <button onClick={openAddModal} className="px-5 py-2.5 bg-gradient-to-r from-primary to-primary-dark text-white rounded-xl hover:shadow-lg hover:shadow-primary/30 transition-all duration-300 text-sm font-semibold flex items-center gap-2">
          <span className="text-lg leading-none">+</span> Create Booking
        </button>
      </div>

      <div className="premium-table-container rounded-none border-x-0 border-b-0">
        <table className="premium-table">
          <thead>
            <tr>
              <th className="premium-th">Job Number</th>
              <th className="premium-th">Customer</th>
              <th className="premium-th">Vehicle</th>
              <th className="premium-th">Complaints</th>
              <th className="premium-th">Status</th>
              <th className="premium-th">Date</th>
              <th className="premium-th text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {bookings.length === 0 ? (
              <tr>
                <td colSpan="7" className="p-8 text-center text-slate-500 dark:text-slate-400">
                  No bookings found.
                </td>
              </tr>
            ) : (
              bookings.map((booking) => (
                <tr key={booking.id} className="premium-tr">
                  <td className="premium-td font-bold text-slate-900 dark:text-white">
                    {booking.jobNumber || `JC-${booking.id}`}
                  </td>
                  <td className="premium-td font-semibold text-slate-700 dark:text-slate-300">
                    {booking.customerName || `Customer #${booking.customerId}`}
                  </td>
                  <td className="premium-td">
                    {booking.vehicleNumber || `Vehicle #${booking.vehicleId}`}
                  </td>
                  <td className="premium-td max-w-[200px] truncate text-slate-500 dark:text-slate-400">
                    {booking.complaints || 'N/A'}
                  </td>
                  <td className="premium-td">
                    <span className={`px-2.5 py-1 rounded-full text-xs font-semibold uppercase tracking-wider ${getStatusColor(booking.status)}`}>
                      {booking.status || 'PENDING'}
                    </span>
                  </td>
                  <td className="premium-td">
                    {booking.createdAt ? new Date(booking.createdAt).toLocaleDateString() : 'N/A'}
                  </td>
                  <td className="premium-td text-right space-x-3">
                    <button onClick={() => openEditModal(booking)} className="text-primary hover:text-primary-dark font-semibold transition-colors">Edit</button>
                    <button onClick={() => handleDelete(booking.id)} className="text-red-500 hover:text-red-700 font-semibold transition-colors">Delete</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <Modal isOpen={isModalOpen} onClose={closeModal} title={editingId ? "Edit Booking" : "Create New Booking"} fullScreen={true}>
        <form onSubmit={handleSubmit} className="space-y-3">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Customer ID</label>
              <input required type="number" name="customerId" value={formData.customerId} onChange={handleInputChange} className="input-field py-2" placeholder="e.g. 1" />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Vehicle ID</label>
              <input required type="number" name="vehicleId" value={formData.vehicleId} onChange={handleInputChange} className="input-field py-2" placeholder="e.g. 1" />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Status</label>
              <select name="status" value={formData.status} onChange={handleInputChange} className="input-field py-2">
                <option value="Pending">Pending</option>
                <option value="In Progress">In Progress</option>
                <option value="Completed">Completed</option>
                <option value="Cancelled">Cancelled</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Complaints / Job</label>
              <input required type="text" name="complaints" value={formData.complaints} onChange={handleInputChange} className="input-field py-2" placeholder="Issue..." />
            </div>
          </div>

          <div className="flex justify-end space-x-2 pt-3 border-t border-slate-200 dark:border-slate-700/50">
            <button type="button" onClick={closeModal} className="px-5 py-2 text-xs font-semibold text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700 transition-colors">Cancel</button>
            <button type="submit" disabled={mutation.isPending} className="px-5 py-2 text-xs font-semibold text-white bg-gradient-to-r from-primary to-primary-dark hover:shadow-lg hover:shadow-primary/30 rounded-lg disabled:opacity-50 transition-all duration-300">
              {mutation.isPending ? 'Saving...' : 'Save'}
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Bookings;

import { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import api from '../../api/axiosConfig';
import toast from 'react-hot-toast';

const Customers = () => {
  const queryClient = useQueryClient();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  
  // Form State
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    role: 'Customer',
    car_brand: 'Hyundai',
    car_model: '',
    car_number: '',
    created_at: new Date().toISOString().split('T')[0]
  });

  const { data: customersData, isLoading } = useQuery({
    queryKey: ['customers'],
    queryFn: () => api.get('/customers')
  });

  const mutation = useMutation({
    mutationFn: (customerData) => {
      if (editingId) {
        return api.put(`/customers/${editingId}`, customerData);
      }
      return api.post('/customers', customerData);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['customers'] });
      toast.success(editingId ? 'Customer updated successfully!' : 'Customer added successfully!');
      closeModal();
    },
    onError: (err) => {
      toast.error(err?.response?.data?.message || 'Something went wrong');
    }
  });

  const deleteMutation = useMutation({
    mutationFn: (id) => api.delete(`/customers/${id}`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['customers'] });
      toast.success('Customer deleted successfully!');
    }
  });

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    mutation.mutate(formData);
  };

  const handleDelete = (id) => {
    if(window.confirm('Are you sure you want to delete this customer?')) {
      deleteMutation.mutate(id);
    }
  };

  const openAddModal = () => {
    setEditingId(null);
    setFormData({ 
      name: '', 
      email: '', 
      phone: '', 
      role: 'Customer',
      car_brand: 'Hyundai',
      car_model: '',
      car_number: '',
      created_at: new Date().toISOString().split('T')[0]
    });
    setIsModalOpen(true);
  };

  const openEditModal = (customer) => {
    setEditingId(customer.id);
    setFormData({
      name: customer.name || '',
      email: customer.email || '',
      phone: customer.mobile || '',
      role: 'Customer',
      car_brand: customer.car_brand || 'Hyundai',
      car_model: customer.car_model || '',
      car_number: customer.car_number || '',
      created_at: customer.createdAt ? new Date(customer.createdAt).toISOString().split('T')[0] : new Date().toISOString().split('T')[0]
    });
    setIsModalOpen(true);
  };

  const closeModal = () => {
    setIsModalOpen(false);
    setEditingId(null);
  };

  if (isLoading) return <div className="p-8 text-center text-gray-500">Loading Customers...</div>;

  const customersDataRaw = customersData?.data || [];
  // Sort customers by ID ascending (1, 2, 3...)
  const customers = [...customersDataRaw].sort((a, b) => a.id - b.id);

  return (
    <div className="glass-panel rounded-2xl overflow-hidden animate-fade-in">
      <div className="p-6 border-b border-slate-200/50 dark:border-slate-700/50 flex justify-between items-center bg-white/50 dark:bg-slate-900/50">
        <h2 className="text-xl font-bold text-slate-900 dark:text-white">Customer Directory</h2>
        <button onClick={openAddModal} className="px-5 py-2.5 bg-gradient-to-r from-primary to-primary-dark text-white rounded-xl hover:shadow-lg hover:shadow-primary/30 transition-all duration-300 text-sm font-semibold flex items-center gap-2">
          <span className="text-lg leading-none">+</span> Add Customer
        </button>
      </div>

      <div className="premium-table-container rounded-none border-x-0 border-b-0">
        <table className="premium-table">
          <thead>
            <tr>
              <th className="premium-th">ID</th>
              <th className="premium-th">Name</th>
              <th className="premium-th">Contact Info</th>
              <th className="premium-th">Joined</th>
              <th className="premium-th">Vehicles</th>
              <th className="premium-th text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {customers.length === 0 ? (
              <tr>
                <td colSpan="6" className="p-8 text-center text-gray-500 dark:text-gray-400">
                  No customers found.
                </td>
              </tr>
            ) : (
              customers.map((customer, idx) => (
                <tr key={customer.id} className="premium-tr">
                  <td className="premium-td font-semibold text-slate-900 dark:text-white">
                    #{idx + 1}
                  </td>
                  <td className="premium-td font-bold text-slate-900 dark:text-white">
                    {customer.name}
                  </td>
                  <td className="premium-td">
                    <div className="flex flex-col">
                      {customer.email && typeof customer.email === 'string' && !customer.email.includes('@dummy.com') && (
                        <span>{customer.email}</span>
                      )}
                      {customer.phone && (
                        <span className={(customer.email && typeof customer.email === 'string' && !customer.email.includes('@dummy.com')) ? "text-xs text-slate-400" : ""}>
                          {customer.phone}
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="premium-td">
                    {customer.joined ? new Date(customer.joined).toLocaleDateString() : 'N/A'}
                  </td>
                  <td className="premium-td">
                    {customer.vehicle || <span className="text-slate-400 italic">No vehicles</span>}
                  </td>
                  <td className="premium-td text-right space-x-3">
                    <button onClick={() => openEditModal(customer)} className="text-primary hover:text-primary-dark font-semibold transition-colors">Edit</button>
                    <button onClick={() => handleDelete(customer.id)} className="text-red-500 hover:text-red-700 font-semibold transition-colors">Delete</button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <Modal isOpen={isModalOpen} onClose={closeModal} title={editingId ? "Edit Customer" : "Add New Customer"} fullScreen={true}>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Full Name</label>
              <input required type="text" name="name" value={formData.name} onChange={handleInputChange} className="input-field" placeholder="John Doe" />
            </div>
            <div>
              <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Joining Date</label>
              <input required type="date" name="created_at" value={formData.created_at} onChange={handleInputChange} className="input-field" />
            </div>

            <div>
              <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Email Address</label>
              <input required type="email" name="email" value={formData.email} onChange={handleInputChange} className="input-field" placeholder="john@example.com" />
            </div>
            <div>
              <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Phone Number</label>
              <input required type="text" name="phone" value={formData.phone} onChange={handleInputChange} className="input-field" placeholder="+91 9876543210" />
            </div>
            
            <div className="col-span-1 md:col-span-2 border-t border-slate-200 dark:border-slate-700/50 pt-4 mt-2">
              <h4 className="text-md font-bold text-slate-900 dark:text-white mb-4">Vehicle Details (Optional)</h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Car Brand</label>
                  <input type="text" name="car_brand" value={formData.car_brand} onChange={handleInputChange} className="input-field" placeholder="e.g. Hyundai" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Car Model</label>
                  <input type="text" name="car_model" value={formData.car_model} onChange={handleInputChange} className="input-field" placeholder="e.g. i20" />
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Car Number</label>
                  <input type="text" name="car_number" value={formData.car_number} onChange={handleInputChange} className="input-field" placeholder="e.g. MH 12 AB 1234" />
                </div>
              </div>
            </div>
          </div>

          <div className="flex justify-end space-x-3 pt-6 border-t border-slate-200 dark:border-slate-700/50">
            <button type="button" onClick={closeModal} className="px-6 py-2.5 text-sm font-semibold text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-xl dark:bg-slate-800 dark:text-slate-300 dark:hover:bg-slate-700 transition-colors">Cancel</button>
            <button type="submit" disabled={mutation.isPending} className="px-6 py-2.5 text-sm font-semibold text-white bg-gradient-to-r from-primary to-primary-dark hover:shadow-lg hover:shadow-primary/30 rounded-xl disabled:opacity-50 transition-all duration-300">
              {mutation.isPending ? 'Saving...' : 'Save Customer'}
            </button>
          </div>
        </form>
      </Modal>
    </div>
  );
};

export default Customers;

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { Users, Car, CalendarCheck, Wrench, IndianRupee, TrendingUp } from "lucide-react";

const getStatusBadge = (status) => {
  const s = (status || 'Pending').toUpperCase();
  const map = {
    'COMPLETED': 'success',
    'IN PROGRESS': 'info',
    'PENDING': 'warning',
    'CONFIRMED': 'default'
  };
  return <Badge variant={map[s] || 'default'}>{status || 'Pending'}</Badge>;
};

const columns = [
  { header: "ID", accessor: "id", cell: (row, idx) => <span className="font-semibold text-slate-900 dark:text-white">{idx + 1}</span> },
  { header: "Customer", accessor: "customer" },
  { header: "Vehicle", accessor: "vehicle" },
  { header: "Service Type", accessor: "type" },
  { header: "Date", accessor: "date" },
  { header: "Status", accessor: "status", cell: (row) => getStatusBadge(row.status) },
];

export default function Dashboard() {
  const navigate = useNavigate();
  const [statsData, setStatsData] = useState(null);
  const [recentBookings, setRecentBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  // Modal State
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [selectedBooking, setSelectedBooking] = useState(null);
  const [editingId, setEditingId] = useState(null);
  const [statusForm, setStatusForm] = useState("");

  useEffect(() => {
    Promise.all([
      fetch("http://localhost:5000/api/dashboard/stats").then(res => res.json()),
      fetch("http://localhost:5000/api/dashboard/recent").then(res => res.json())
    ])
      .then(([statsRes, recentRes]) => {
        setStatsData(statsRes);
        if (Array.isArray(recentRes)) setRecentBookings(recentRes);
        setLoading(false);
      })
      .catch(err => {
        console.error("Dashboard fetch error:", err);
        setLoading(false);
      });
  }, []);

  const handleAction = async (action, row) => {
    if (action === 'view') {
      setSelectedBooking(row);
      setIsViewModalOpen(true);
    } else if (action === 'edit') {
      setEditingId(row.id);
      setStatusForm(row.status || 'Pending');
      setIsEditModalOpen(true);
    } else if (action === 'delete') {
      if (window.confirm("Are you sure you want to delete this booking?")) {
        try {
          const res = await fetch(`http://localhost:5000/api/bookings/${row.id}`, { method: 'DELETE' });
          if (res.ok) {
            setRecentBookings(recentBookings.filter(b => b.id !== row.id));
          }
        } catch (err) {
          console.error("Error deleting:", err);
        }
      }
    }
  };

  const handleEditSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(`http://localhost:5000/api/bookings/${editingId}/status`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: statusForm })
      });
      if (res.ok) {
        setRecentBookings(recentBookings.map(b => b.id === editingId ? { ...b, status: statusForm } : b));
        setIsEditModalOpen(false);
      }
    } catch (err) {
      console.error("Error updating status:", err);
    }
  };

  const stats = [
    { name: "Total Customers", value: statsData?.totalCustomers || "0", icon: Users, change: "0%", trend: "up" },
    { name: "Total Vehicles", value: statsData?.totalVehicles || "0", icon: Car, change: "0%", trend: "up" },
    { name: "Today's Bookings", value: statsData?.todayBookings || "0", icon: CalendarCheck, change: "0%", trend: "up" },
    { name: "Pending Services", value: statsData?.pendingServices || "0", icon: Wrench, change: "0%", trend: "up" },
    { name: "Monthly Revenue", value: statsData?.monthlyRevenue || "₹0", icon: IndianRupee, change: "0%", trend: "up" },
    { name: "Total Earnings", value: statsData?.totalEarnings || "₹0", icon: TrendingUp, change: "0%", trend: "up" },
  ];

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight">Dashboard Overview</h1>
        <p className="text-slate-500 dark:text-slate-400">Welcome back, here's what's happening today.</p>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {stats.map((stat, i) => (
          <div key={i} className="glass-panel rounded-2xl p-6 flex flex-col gap-4 group hover:-translate-y-1 transition-all duration-300">
            <div className="flex items-center justify-between">
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-primary/20 to-primary/5 flex items-center justify-center text-primary dark:text-white group-hover:scale-110 transition-transform duration-300 border border-primary/10">
                <stat.icon className="w-6 h-6 drop-shadow-md" />
              </div>
              <span className={`text-xs font-semibold px-2.5 py-1 rounded-full ${stat.trend === 'up' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-400' : 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-400'}`}>
                {stat.change}
              </span>
            </div>
            <div>
              <p className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight">{loading ? "..." : stat.value}</p>
              <p className="text-sm font-medium text-slate-500 dark:text-slate-400 mt-1">{stat.name}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="glass-panel rounded-2xl lg:col-span-2 min-h-[380px] p-2 overflow-hidden">
          <RevenueChart />
        </div>
        <div className="glass-panel rounded-2xl min-h-[380px] p-2 overflow-hidden">
          <CategoryChart />
        </div>
      </div>

      {/* Recent Bookings Table */}
      <div className="glass-panel rounded-2xl overflow-hidden p-0">
        <div className="p-6 border-b border-slate-200/50 dark:border-slate-700/50 flex items-center justify-between">
          <h2 className="text-xl font-bold text-slate-900 dark:text-white">Recent Bookings</h2>
          <button onClick={() => navigate('/admin/bookings')} className="text-sm text-primary font-semibold hover:text-primary-dark transition-colors">View All &rarr;</button>
        </div>
        {loading ? (
          <div className="h-64 flex items-center justify-center text-slate-500 bg-surface-light dark:bg-surface-dark border border-t-0 border-slate-200 dark:border-slate-800 rounded-b-lg">
            Loading recent bookings...
          </div>
        ) : (
          <Table
            columns={columns}
            data={recentBookings}
            actions={['view', 'edit', 'delete']}
            onAction={handleAction}
          />
        )}
      </div>

      <Modal isOpen={isViewModalOpen} onClose={() => setIsViewModalOpen(false)} title="Booking Details">
        {selectedBooking && (
          <div className="space-y-4">
            <div className="bg-slate-50 dark:bg-slate-800/50 p-4 rounded-lg space-y-3">
              <div className="flex justify-between">
                <span className="text-slate-500 text-sm">Booking ID</span>
                <span className="font-medium text-slate-900 dark:text-white">#{selectedBooking.id}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-500 text-sm">Customer</span>
                <span className="font-medium text-slate-900 dark:text-white">{selectedBooking.customer}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-500 text-sm">Vehicle</span>
                <span className="font-medium text-slate-900 dark:text-white">{selectedBooking.vehicle}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-500 text-sm">Service Type</span>
                <span className="font-medium text-slate-900 dark:text-white max-w-[200px] text-right truncate" title={selectedBooking.type}>{selectedBooking.type}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-500 text-sm">Date</span>
                <span className="font-medium text-slate-900 dark:text-white">{selectedBooking.date}</span>
              </div>
              <div className="flex justify-between items-center mt-2 pt-2 border-t border-slate-200 dark:border-slate-700">
                <span className="text-slate-500 text-sm">Status</span>
                <span>{getStatusBadge(selectedBooking.status)}</span>
              </div>
            </div>
            <div className="pt-2 flex justify-end">
              <button onClick={() => setIsViewModalOpen(false)} className="btn-primary">Close</button>
            </div>
          </div>
        )}
      </Modal>

      <Modal isOpen={isEditModalOpen} onClose={() => setIsEditModalOpen(false)} title="Update Booking Status">
        <form onSubmit={handleEditSubmit} className="space-y-4">
          <div className="space-y-1">
            <label className="text-sm font-medium text-slate-700 dark:text-slate-300">Status</label>
            <select className="input-field" value={statusForm} onChange={e => setStatusForm(e.target.value)}>
              <option value="Pending">Pending</option>
              <option value="Confirmed">Confirmed</option>
              <option value="In Progress">In Progress</option>
              <option value="Completed">Completed</option>
            </select>
          </div>
          <div className="pt-4 flex justify-end gap-3 border-t border-slate-200 dark:border-slate-800">
            <button type="button" onClick={() => setIsEditModalOpen(false)} className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white transition-colors">Cancel</button>
            <button type="submit" className="btn-primary">Save Changes</button>
          </div>
        </form>
      </Modal>

    </div>
  );
}

import { useState, useEffect } from "react";

export default function Enquiries() {
  const [enquiries, setEnquiries] = useState([]);
  const [loading, setLoading] = useState(true);

  const [isReplyModalOpen, setIsReplyModalOpen] = useState(false);
  const [selectedEnquiry, setSelectedEnquiry] = useState(null);
  const [replyMessage, setReplyMessage] = useState("");

  useEffect(() => {
    fetch("http://localhost:5000/api/enquiries")
      .then((res) => res.json())
      .then((data) => {
        setEnquiries(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Failed to fetch enquiries:", err);
        setLoading(false);
      });
  }, []);

  const openReplyModal = (enq) => {
    setSelectedEnquiry(enq);
    setReplyMessage("");
    setIsReplyModalOpen(true);
  };

  const handleSendReply = () => {
    // Mock sending reply
    setEnquiries(enquiries.map(e =>
      e.id === selectedEnquiry.id ? { ...e, status: "Resolved" } : e
    ));
    setIsReplyModalOpen(false);
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <div>
        <h1 className="text-3xl font-bold text-slate-900 dark:text-white tracking-tight">Contact Enquiries</h1>
        <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">View and respond to customer questions and messages.</p>
      </div>

      <div className="grid grid-cols-1 gap-6">
        {loading ? (
          <p className="text-slate-500">Loading enquiries...</p>
        ) : enquiries.length === 0 ? (
          <p className="text-slate-500">No enquiries found.</p>
        ) : (
          enquiries.map((enq) => (
            <div key={enq.id} className="glass-panel rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow">
              <div className="flex flex-col sm:flex-row sm:items-start justify-between gap-4 mb-4">
                <div className="flex items-start gap-4">
                  <div className="w-12 h-12 rounded-full bg-gradient-to-br from-blue-500/20 to-blue-500/5 flex items-center justify-center text-blue-600 dark:text-blue-400 shrink-0 border border-blue-500/10">
                    <MessageSquare className="w-5 h-5" />
                  </div>
                  <div>
                    <h3 className="font-bold text-slate-900 dark:text-white text-lg tracking-tight">{enq.subject}</h3>
                    <p className="text-sm font-semibold text-slate-700 dark:text-slate-300 mt-0.5">{enq.name}</p>
                    <div className="flex flex-wrap items-center gap-3 text-xs text-slate-500 mt-2 font-medium">
                      <span className="flex items-center gap-1.5"><Mail className="w-3.5 h-3.5" /> {enq.email}</span>
                      <span className="flex items-center gap-1.5"><Phone className="w-3.5 h-3.5" /> {enq.phone}</span>
                      <span className="flex items-center gap-1.5"><Calendar className="w-3.5 h-3.5" /> {enq.date}</span>
                    </div>
                  </div>
                </div>
                <div className={`px-3 py-1.5 rounded-full text-xs font-semibold border ${enq.status === 'New' ? 'bg-blue-50 text-blue-700 border-blue-200 dark:bg-blue-900/30 dark:text-blue-400 dark:border-blue-800' : 'bg-emerald-50 text-emerald-700 border-emerald-200 dark:bg-emerald-900/30 dark:text-emerald-400 dark:border-emerald-800'}`}>
                  {enq.status}
                </div>
              </div>

              <div className="bg-slate-50/50 dark:bg-slate-800/30 p-5 rounded-xl text-sm text-slate-700 dark:text-slate-300 leading-relaxed border border-slate-200 dark:border-slate-700/50">
                "{enq.message}"
              </div>

              <div className="mt-4 flex justify-end">
                <button
                  onClick={() => openReplyModal(enq)}
                  className="flex items-center gap-2 px-4 py-2 bg-primary text-white rounded-lg text-sm font-medium hover:bg-primary-dark transition-colors"
                >
                  <Reply className="w-4 h-4" /> Reply
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Reply Modal */}
      <Modal isOpen={isReplyModalOpen} onClose={() => setIsReplyModalOpen(false)} title="Reply to Enquiry">
        {selectedEnquiry && (
          <div className="space-y-4">
            <div className="bg-slate-50 dark:bg-slate-800/50 p-3 rounded-lg border border-slate-100 dark:border-slate-700/50">
              <p className="text-sm font-medium text-slate-900 dark:text-white">To: {selectedEnquiry.name} ({selectedEnquiry.email})</p>
              <p className="text-sm text-slate-500 mt-1">Re: {selectedEnquiry.subject}</p>
            </div>

            <div>
              <label className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1 block">Your Message</label>
              <textarea
                rows={5}
                value={replyMessage}
                onChange={(e) => setReplyMessage(e.target.value)}
                placeholder="Type your reply here..."
                className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-primary/50 dark:text-white"
              ></textarea>
            </div>

            <div className="pt-4 flex justify-end gap-3">
              <button onClick={() => setIsReplyModalOpen(false)} className="px-4 py-2 text-sm font-medium text-slate-700 bg-slate-100 hover:bg-slate-200 rounded-lg">Cancel</button>
              <button
                onClick={handleSendReply}
                disabled={!replyMessage.trim()}
                className="px-4 py-2 text-sm font-medium text-white bg-primary hover:bg-primary-dark rounded-lg flex items-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                <Reply className="w-4 h-4" /> Send Reply
              </button>
            </div>
          </div>
        )}
      </Modal>

    </div>
  );
}

import { useQuery } from '@tanstack/react-query';
import api from '../../api/axiosConfig';

const Invoices = () => {
  const { data: invoicesData, isLoading } = useQuery({
    queryKey: ['invoices'],
    queryFn: () => api.get('/invoices')
  });

  if (isLoading) return <div className="p-8 text-center text-gray-500">Loading Invoices...</div>;

  const invoices = invoicesData?.data || [];

  const getStatusColor = (status) => {
    switch (status) {
      case 'Paid': return 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-500';
      case 'Unpaid': return 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-500';
      case 'Partial': return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-500';
      default: return 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-300';
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this invoice? This will also delete the associated booking.')) {
      try {
        await api.delete(`/bookings/${id}`);
        window.location.reload();
      } catch (err) {
        console.error(err);
        alert('Failed to delete invoice');
      }
    }
  };

  return (
    <div className="glass-panel rounded-2xl overflow-hidden animate-fade-in">
      <div className="p-6 border-b border-slate-200 dark:border-slate-700 flex justify-between items-center bg-white/50 dark:bg-slate-900/50">
        <h2 className="text-xl font-bold text-slate-900 dark:text-white">Invoices & Billing</h2>
      </div>

      <div className="premium-table-container rounded-none border-x-0 border-b-0">
        <table className="premium-table">
          <thead>
            <tr>
              <th className="premium-th">Invoice #</th>
              <th className="premium-th">Job Card</th>
              <th className="premium-th">Customer</th>
              <th className="premium-th">Amount</th>
              <th className="premium-th">Status</th>
              <th className="premium-th">Date</th>
              <th className="premium-th text-right">Actions</th>
            </tr>
          </thead>
          <tbody>
            {invoices.length === 0 ? (
              <tr>
                <td colSpan="7" className="p-8 text-center text-slate-500 dark:text-slate-400">
                  No invoices generated yet.
                </td>
              </tr>
            ) : (
              invoices.map((invoice) => (
                <tr key={invoice.id} className="premium-tr">
                  <td className="premium-td font-bold text-slate-900 dark:text-white">
                    {invoice.invoiceNumber || `INV-${invoice.id}`}
                  </td>
                  <td className="premium-td text-slate-700 dark:text-slate-300">
                    {invoice.jobNumber || `JC-${invoice.jobCardId}`}
                  </td>
                  <td className="premium-td font-semibold text-slate-700 dark:text-slate-300">
                    {invoice.customerName || 'N/A'}
                  </td>
                  <td className="premium-td font-semibold text-slate-900 dark:text-white">
                    ₹{invoice.totalAmount}
                  </td>
                  <td className="premium-td">
                    <span className={`px-2.5 py-1 rounded-full text-xs font-semibold ${getStatusColor(invoice.paymentStatus || 'Unpaid')}`}>
                      {invoice.paymentStatus || 'Unpaid'}
                    </span>
                  </td>
                  <td className="premium-td">
                    {invoice.createdAt ? new Date(invoice.createdAt).toLocaleDateString() : 'N/A'}
                  </td>
                  <td className="premium-td text-right space-x-2">
                    <button 
                      onClick={() => window.open(`/admin/invoices/${invoice.id}/print`, '_blank')}
                      className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-blue-100 text-blue-700 hover:bg-blue-200 dark:bg-blue-900/30 dark:text-blue-400 dark:hover:bg-blue-900/50 rounded-lg text-sm font-semibold transition-colors"
                      title="View PDF"
                    >
                      <FileText className="w-4 h-4" /> PDF
                    </button>
                    <button 
                      onClick={() => alert('Please use the Bookings page to edit this invoice details.')}
                      className="inline-flex items-center justify-center w-8 h-8 bg-slate-100 text-slate-600 hover:bg-slate-200 dark:bg-slate-800 dark:text-slate-400 dark:hover:bg-slate-700 rounded-lg transition-colors"
                      title="Edit Invoice"
                    >
                      <Edit className="w-4 h-4" />
                    </button>
                    <button 
                      onClick={() => handleDelete(invoice.id)}
                      className="inline-flex items-center justify-center w-8 h-8 bg-red-100 text-red-600 hover:bg-red-200 dark:bg-red-900/30 dark:text-red-400 dark:hover:bg-red-900/50 rounded-lg transition-colors"
                      title="Delete Invoice"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default Invoices;

import { useState, useEffect } from "react";

